// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address payable caller) public {
        vm.assume(caller != address(0) && caller != address(c));
        // First call
        vm.deal(caller, 10 ether);
        vm.prank(caller);
        (bool success1,) = address(c).call{value: 10}(abi.encodeWithSignature("play()"));

        // Second call
        vm.prank(caller);
        (bool success2,) = address(c).call{value: 10}(abi.encodeWithSignature("play()"));

        // If both succeeded, the invariant: after two consecutive calls, the last random result determines pot.
        // We cannot know random, but the general rule: pot after two calls with same sender and value
        // should either be 0 (if first call paid out and reset pot) or 10 (if first call didn't payout, pot accumulated).
        // The mutant always sets pot to 0 at the start, so after two calls, pot can only be 0 or 10 depending on second call.
        // The reference can also be 0 or 10, but additionally can be 20 if first call didn't payout and second didn't either.
        // So the difference: reference allows pot == 20, mutant never does.
        // Property: if both calls succeeded, pot is never 20.
        if (success1 && success2) {
            assertTrue(c.pot() != 20);
        }
    }
}

