pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        vm.deal(caller, 10);
        vm.prank(caller);
        uint potBefore = c.pot();
        c.play{value: 10}();
        // If the call lost (random == 1), pot should be potBefore + 10.
        // If the call won (random == 0), pot should be 0 in reference.
        // We can't directly observe random, but we can bound potAfter:
        // potAfter is either 0 (win) or potBefore + 10 (loss).
        // After a loss, potAfter > potBefore.
        // After a win, potAfter <= potBefore (since pot becomes 0 and was at least 0).
        // So if potAfter > potBefore, it was a loss and pot must be exactly potBefore + 10.
        uint potAfter = c.pot();
        if (potAfter > potBefore) {
            assertTrue(potAfter == potBefore + 10, "Loss should keep the ticket");
        } else {
            assertTrue(potAfter == 0, "Win should reset pot to 0");
        }
    }
}

