pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(c) && caller != address(0) && caller != address(this) && caller != c.bank());
        vm.deal(caller, 10 ether);

        uint256 balBefore = caller.balance;
        uint256 potBefore = c.pot();

        vm.prank(caller);
        (bool success, ) = address(c).call{value: 10 ether}(abi.encodeWithSignature("play()"));

        uint256 potAfter = c.pot();
        uint256 balAfter = caller.balance;

        if (success) {
            // If the transaction succeeded, the pot was either reset (random == 0) or unchanged (random == 1)
            assertTrue((potAfter == 0) || (potAfter == potBefore + 10 ether));
            // The caller's balance change must be consistent with the expected payout
            // In the reference: if potAfter == 0, caller gained potBefore + 10 - 1 = potBefore + 9 (since pot went up then down)
            // Actually careful: pot before call is potBefore, after adding 10, pot = potBefore + 10, then if random == 0, bank gets 1, caller gets pot - 1 = potBefore + 9, pot = 0
            // So caller's balance change = (potBefore + 9) - 10 = potBefore - 1 (they paid 10, got back potBefore+9)
            // If random == 1, caller loses 10, balance change = -10
            // So the difference modulo 10 is either (potBefore - 1) % 10 or (-10) % 10 = 0
            if (potAfter == 0) {
                assertTrue((balAfter - balBefore + 10 ether - 9 ether) % 10 ether == 0);
            } else {
                assertTrue((balAfter - balBefore + 10 ether) % 10 ether == 0);
            }
        } else {
            // Transaction reverted, caller balance unchanged
            assertTrue(balAfter == balBefore);
        }
    }
}

