            uint potAfter = c.pot();
            // The general rule: bank balance increases by exactly 1 wei if and only if pot becomes zero
            bool bankIncreasedByFee = (bankBalAfter == bankBalBefore + 1);
            bool potIsZero = (potAfter == 0);
            assertTrue(bankIncreasedByFee == potIsZero);
        }
    }
