pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0);
        // Record the pot before the call
        uint256 potBefore = c.pot();
        uint256 balanceBefore = address(c).balance;

        // Try to call play with the given amount
        (bool success, ) = address(c).call{value: amount}(abi.encodeWithSignature("play()"));

        if (success) {
            // If the call succeeded, the pot must be either 0 (if the caller won) or unchanged (if lost)
            uint256 potAfter = c.pot();
            assertTrue(
                potAfter == 0 || potAfter == potBefore + amount,
                "Pot rule violated after successful play"
            );
